extern int32_t 되돌림흐름연결(int32_t,int32_t,int32_t),되돌림흐름연결받기(int32_t),되돌림흐름읽기(int32_t,int32_t),되돌림흐름쓰기(int32_t,int32_t);
extern int32_t 되돌림흐름접속번호(int32_t),되돌림흐름상대(int32_t),되돌림흐름닫기(int32_t);
static int внешний[24];
static int 임의주소[24], 양쪽수신창구[24], UDP_внешний_одноранговый[8], граница_АДРЕС[8];
static int 외부번호(int дескриптор_файла) { return дескриптор_файла>=32 && дескриптор_файла<56 ? внешний[дескриптор_файла-32]-1 : -1; }
static int вставить_SMS(int дескриптор_файла,int ТИП_область) {
    if(дескриптор_файла<32||дескриптор_файла>=56)return -9;int Назад_товар=외부번호(дескриптор_файла);if(Назад_товар>=0)return Назад_товар;
    int товар_СЧЁТ=Create_сокет_участник(ТИП_область);if(товар_СЧЁТ>=0)внешний[дескриптор_файла-32]=товар_СЧЁТ+1;return товар_СЧЁТ;
}
int32_t 자바전문만들기(int32_t 첫째값,int32_t СЕКУНДЫ_ЗНАЧЕН,int32_t код_знака){return 되돌림전문만들기(첫째값,СЕКУНДЫ_ЗНАЧЕН,код_знака);}
int32_t 자바전문묶기(int32_t дескриптор_файла,int32_t адрес_в_Интернете,int32_t номер_порта){
    if(адрес_в_Интернете==0x7f000001)return 되돌림전문묶기(дескриптор_файла,адрес_в_Интернете,номер_порта);
    if(адрес_в_Интернете!=0&&адрес_в_Интернете!=чтение_сеть_статус(0,0))return -99;
    int 반환값=되돌림전문묶기(дескриптор_файла,0,номер_порта);if(반환값<0)return 반환값;
    int товар_СЧЁТ=вставить_SMS(дескриптор_файла,2);if(товар_СЧЁТ<0)return товар_СЧЁТ;반환값=NET_BIND(товар_СЧЁТ,чтение_сеть_статус(0,0),되돌림전문접속번호(дескриптор_файла));if(!반환값)граница_АДРЕС[дескриптор_файла-32]=адрес_в_Интернете;return 반환값;
}
int32_t 자바전문보내기(int32_t дескриптор_файла,int32_t адрес_в_Интернете,int32_t номер_порта,int32_t Размер){
    if(адрес_в_Интернете==0x7f000001)return 되돌림전문보내기(дескриптор_файла,адрес_в_Интернете,номер_порта,Размер);
    if(Размер<0||Размер>512)return -90;if(номер_порта<1||номер_порта>65535)return -22;
    if(되돌림전문접속번호(дескриптор_файла)<0)return -9;
    if(되돌림전문주소(дескриптор_файла)==0x7f000001)return -101;
    int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ<0){int 반환값=0;if(되돌림전문접속번호(дескриптор_файла)==0)반환값=되돌림전문묶기(дескриптор_файла,0,0);if(반환값<0)return 반환값;товар_СЧЁТ=вставить_SMS(дескриптор_файла,2);if(товар_СЧЁТ<0)return товар_СЧЁТ;반환값=NET_BIND(товар_СЧЁТ,чтение_сеть_статус(0,0),되돌림전문접속번호(дескриптор_файла));if(반환값<0)return 반환값;}
    unsigned char данные[512];for(int 순번=0;순번<Размер;순번++)данные[순번]=자바전문얻기(순번);return написать_датаграмма(товар_СЧЁТ,данные,Размер,адрес_в_Интернете,номер_порта);
}
int32_t 자바전문받기(int32_t дескриптор_файла,int32_t Размер){
    int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ<0)return 되돌림전문받기(дескриптор_файла,Размер);if(Размер<0||Размер>512)return -22;
    int локальный=되돌림전문받기(дескриптор_файла,Размер);if(локальный!=-11){UDP_внешний_одноранговый[дескриптор_файла-32]=0;return локальный;}
    unsigned char данные[512];int 반환값=получить_датаграмма(товар_СЧЁТ,данные,Размер);if(반환값>=0)UDP_внешний_одноранговый[дескриптор_файла-32]=1;for(int 순번=0;순번<반환값;순번++)자바전문넣기(순번,данные[순번]);return 반환값;
}
int32_t 자바전문접속번호(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);return товар_СЧЁТ<0?되돌림전문접속번호(дескриптор_файла):(int32_t)сеть_номер_порта(товар_СЧЁТ);}
int32_t 자바전문주소(int32_t дескриптор_файла){return 외부번호(дескриптор_файла)<0?되돌림전문주소(дескриптор_файла):граница_АДРЕС[дескриптор_файла-32];}
int32_t 자바전문상대(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);return товар_СЧЁТ<0||!UDP_внешний_одноранговый[дескриптор_файла-32]?되돌림전문상대(дескриптор_файла):(int32_t)одноранговый_номер_порта(товар_СЧЁТ);}
int32_t 자바전문원격주소(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);return товар_СЧЁТ<0||!UDP_внешний_одноранговый[дескриптор_файла-32]?0x7f000001:(int32_t)NET_одноранговый_АДРЕС(товар_СЧЁТ);}
int32_t 자바전문닫기(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ>=0){Close_сеть(товар_СЧЁТ);внешний[дескриптор_файла-32]=0;}if(дескриптор_файла>=32&&дескриптор_файла<40)UDP_внешний_одноранговый[дескриптор_файла-32]=граница_АДРЕС[дескриптор_файла-32]=0;return 되돌림전문닫기(дескриптор_файла);}
int32_t 자바흐름만들기(void){return 되돌림흐름만들기();}
int32_t 자바흐름묶기(int32_t дескриптор_файла,int32_t адрес_в_Интернете,int32_t номер_порта){
    if(адрес_в_Интернете==0||адрес_в_Интернете==0x7f000001){int 반환값=되돌림흐름묶기(дескриптор_файла,адрес_в_Интернете,номер_порта);if(!반환값)임의주소[дескриптор_файла-32]=адрес_в_Интернете==0;return 반환값;}
    if(адрес_в_Интернете!=чтение_сеть_статус(0,0))return -99;int 반환값=되돌림흐름묶기(дескриптор_файла,0,номер_порта);if(반환값<0)return 반환값;
    int товар_СЧЁТ=вставить_SMS(дескриптор_файла,1);return товар_СЧЁТ<0?товар_СЧЁТ:NET_BIND(товар_СЧЁТ,адрес_в_Интернете,되돌림흐름접속번호(дескриптор_файла));
}
int32_t 자바흐름듣기(int32_t дескриптор_файла,int32_t невыполненная_работа){
    int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ<0){int 반환값=되돌림흐름듣기(дескриптор_файла,невыполненная_работа);if(반환값<0||!임의주소[дескриптор_файла-32])return 반환값;
        товар_СЧЁТ=вставить_SMS(дескриптор_файла,1);if(товар_СЧЁТ<0)return товар_СЧЁТ;반환값=NET_BIND(товар_СЧЁТ,чтение_сеть_статус(0,0),되돌림흐름접속번호(дескриптор_файла));if(반환값<0)return 반환값;양쪽수신창구[дескриптор_файла-32]=1;
    }return невыполненная_работа<1?-22:NET_ожидать_передачи_данных(товар_СЧЁТ);
}
int32_t 자바흐름연결(int32_t дескриптор_файла,int32_t адрес_в_Интернете,int32_t номер_порта){
    if(адрес_в_Интернете==0x7f000001 && 외부번호(дескриптор_файла)<0)return 되돌림흐름연결(дескриптор_файла,адрес_в_Интернете,номер_порта);
    if(되돌림흐름접속번호(дескриптор_файла)<0)return -9;int товар_СЧЁТ=вставить_SMS(дескриптор_файла,1);return товар_СЧЁТ<0?товар_СЧЁТ:NET_Connect(товар_СЧЁТ,адрес_в_Интернете,номер_порта);
}
int32_t 자바흐름연결받기(int32_t дескриптор_файла){
    int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ<0)return 되돌림흐름연결받기(дескриптор_файла);
    if(양쪽수신창구[дескриптор_файла-32]){int локальный=되돌림흐름연결받기(дескриптор_файла);if(локальный!=-11)return локальный;}
    int одноранговый_ЗНАЧЕН=NET_принять(товар_СЧЁТ);if(одноранговый_ЗНАЧЕН<0)return одноранговый_ЗНАЧЕН;
    int целевое_значение=되돌림흐름만들기();if(целевое_значение<0){Close_сеть(одноранговый_ЗНАЧЕН);return целевое_значение;}внешний[целевое_значение-32]=одноранговый_ЗНАЧЕН+1;return целевое_значение;
}
int32_t 자바흐름읽기(int32_t дескриптор_файла,int32_t Размер){
    int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ<0)return 되돌림흐름읽기(дескриптор_файла,Размер);if(Размер<0||Размер>512)return -22;
    unsigned char данные[512];int 반환값=NET_чтение(товар_СЧЁТ,данные,Размер);for(int 순번=0;순번<반환값;순번++)자바전문넣기(순번,данные[순번]);return 반환값;
}
int32_t 자바흐름쓰기(int32_t дескриптор_файла,int32_t Размер){
    int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ<0)return 되돌림흐름쓰기(дескриптор_файла,Размер);if(Размер<0||Размер>512)return -22;
    unsigned char данные[512];for(int 순번=0;순번<Размер;순번++)данные[순번]=자바전문얻기(순번);return NET_запись(товар_СЧЁТ,данные,Размер);
}
int32_t 자바흐름접속번호(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);return товар_СЧЁТ<0?되돌림흐름접속번호(дескриптор_файла):(int32_t)сеть_номер_порта(товар_СЧЁТ);}
int32_t 자바흐름상대(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);return товар_СЧЁТ<0?되돌림흐름상대(дескриптор_файла):(int32_t)одноранговый_номер_порта(товар_СЧЁТ);}
int32_t 자바흐름주소(int32_t дескриптор_файла){return 외부번호(дескриптор_файла)<0?0x7f000001:양쪽수신창구[дескриптор_файла-32]?0:чтение_сеть_статус(0,0);}
int32_t 자바흐름닫기(int32_t дескриптор_файла){int товар_СЧЁТ=외부번호(дескриптор_файла);if(товар_СЧЁТ>=0){Close_сеть(товар_СЧЁТ);внешний[дескриптор_файла-32]=0;}if(дескриптор_файла>=40&&дескриптор_файла<56)임의주소[дескриптор_файла-32]=양쪽수신창구[дескриптор_файла-32]=0;return 되돌림흐름닫기(дескриптор_файла);}
